// Récupération du body envoyé par Tally
const body = $input.first().json.body;

if (!body || !body.data || !Array.isArray(body.data.fields)) {
  throw new Error('Structure Tally invalide : champ data.fields manquant ou mal formé.');
}

const fields = body.data.fields;

function getField(label) {
  const field = fields.find(f => f.label && f.label.trim() === label.trim());
  if (!field || field.value === null || field.value === undefined || field.value === '') {
    return 'Non renseigné';
  }
  if (Array.isArray(field.value)) {
    return field.value.join(', ') || 'Non renseigné';
  }
  return String(field.value).trim() || 'Non renseigné';
}

const nom        = getField('Prénom et Nom');
const email      = getField('Email professionnel');
const site       = getField('Site e-commerce (URL)');
const plateforme = getField('Plateforme utilisée');
const probleme   = getField('Problème principal');
const objectif   = getField('Objectif business principal');
const budget     = getField('Budget estimé');
const urgence    = getField('Urgence');
const ca         = getField('Taille de la boutique');
const autoExist  = getField('Automatisations déjà en place');
const source     = getField('Source de découverte');

let dateFormatee = 'Non renseignée';
try {
  const rawDate = body.data.submittedAt || body.createdAt;
  if (rawDate) {
    const d = new Date(rawDate);
    dateFormatee = d.toLocaleString('fr-FR', {
      timeZone: 'Europe/Paris',
      day: '2-digit', month: '2-digit', year: 'numeric',
      hour: '2-digit', minute: '2-digit'
    });
  }
} catch (e) { dateFormatee = 'Non renseignée'; }

return [{
  json: {
    nom, email, site, plateforme, probleme, objectif,
    budget, urgence, ca, autoExist, source,
    date: dateFormatee,
    responseId: body.data.responseId || 'N/A',
    eventId: body.eventId || 'N/A'
  }
}];

