// Récupérer le contenu IA
let aiContent = '';
try {
  aiContent = $input.first().json.choices[0].message.content || '';
} catch(e) {
  aiContent = '<p>Contenu indisponible — veuillez contacter AutoFlow AI directement.</p>';
}

// Récupérer les données client depuis le node précédent
