  <div class="footer-brand">⚡ AutoFlow AI</div>
  <small>Expert n8n &amp; Automatisation IA pour E-commerçants</small>
</div>
</body>
</html>`;

return [{ json: { html, nom: client.nom, email: client.email, site: client.site } }];

// Construire le lien de téléchargement direct depuis l'ID du fichier Drive
const fileId = $('Convertir HTML → PDF (Google Drive)').first().json.id;
const nom    = $('Préparer HTML Rapport').first().json.nom;
const email  = $('Préparer HTML Rapport').first().json.email;
const site   = $('Préparer HTML Rapport').first().json.site;

const pdfLink = `https://drive.google.com/file/d/${fileId}/view?usp=sharing`;
const downloadLink = `https://drive.google.com/uc?export=download&id=${fileId}`;

return [{ json: { pdfLink, downloadLink, fileId, nom, email, site } }];

